"""Combine the complete 96-run normalization study with its current softmax controls."""

import copy
import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path


ROOT = Path('/tmp/transformer-qknorm-study')
EXPERIMENT = ROOT / 'experiments/basis_qknorm'
STATE = Path('/tmp/qknorm-study-supervisor.json')
ARMS = ('learned-dot-one', 'learned-dot-matched')


def sha(path):
    with path.open('rb') as source:
        return hashlib.file_digest(source, 'sha256').hexdigest()


def main():
    state = json.loads(STATE.read_text())
    assert state['phase'] == 'training_complete', 'The complete planned training is required'
    parts = {size: json.loads((EXPERIMENT / f'{size}_results.json').read_text())
             for size in ('small', 'large')}
    assert len(parts['small']['runs']) == 45 and len(parts['large']['runs']) == 51
    runs = {label: run for part in parts.values() for label, run in part['runs'].items()}
    assert len(runs) == 96 and set(runs) == set(state['completed_labels'])
    code_pin = state['runtime_code_sha256']
    source_pin = sha(EXPERIMENT / 'experiment.py')
    assert all(sha(ROOT / 'python/src/lab' / path) == digest for path, digest in code_pin.items())
    for part in parts.values():
        assert part['runtime_code_sha256'] == code_pin
        assert part['experiment_source_sha256'] == source_pin == state['experiment_source_sha256']
        assert part['preparation_sha256'] == sha(EXPERIMENT / 'preparation.json')
        assert hashlib.sha256(part['program_source'].encode()).hexdigest() == part['program_sha256']
        assert hashlib.sha256(part['helper_source'].encode()).hexdigest() == part['helper_sha256']
    raw_verified = 0
    for label, run in runs.items():
        assert run['runtime_source_code_verified']
        assert all(sha(EXPERIMENT / path) == digest for path, digest in run['source'].items()), label
        raw_verified += len(run['source'])
        assert (run['pass_step'] is not None) == (run['stop']['reason'] == 'solved'), label
        assert len(run['final_heads']) == (2 if '-small-' in label else 6), label
    comparisons = {}
    for arm in ARMS:
        required, matched, sparse, extra, dense = [], [], [], [], []
        chosen = {label: run for label, run in runs.items() if run['arm'] == arm}
        assert len(chosen) == 30
        for label, run in chosen.items():
            control_label = 'softmax-' + run['suffix']
            control = runs[control_label]
            description = copy.deepcopy(control['description'])
            for field in ('scores', 'weights'):
                description['model']['block']['attention'][field] = run['description']['model']['block']['attention'][field]
            assert description == run['description'], label
            assert run['trajectory'][0]['rows_sha256'] == control['trajectory'][0]['rows_sha256'], label
            if control['pass_step'] is not None:
                required.append(label)
                if run['pass_step'] is not None:
                    matched.append(label)
                    if not run['final_sparsity']['dense_only']:
                        sparse.append(label)
                    else:
                        dense.append(label)
            elif run['pass_step'] is not None:
                extra.append(label)
        comparisons[arm] = {
            'runs': len(chosen), 'required_softmax_passes': len(required),
            'matched_required_passes': len(matched), 'sparse_matched_required_passes': len(sparse),
            'all_passes': len(matched) + len(extra),
            'required_labels': required, 'matched_labels': matched,
            'unmatched_softmax_labels': [label for label in required if label not in matched],
            'dense_only_matched_labels': dense, 'extra_passes_where_softmax_fails': extra,
            'passes_complete_basis_criterion': len(sparse) == len(required),
            'by_size': {size: parts[size]['comparisons'][arm] for size in parts},
        }
        for field in ('required_softmax_passes', 'matched_required_passes', 'sparse_matched_required_passes', 'all_passes'):
            assert comparisons[arm][field] == sum(parts[size]['comparisons'][arm][field] for size in parts)
    cells = {}
    for mode, task in (('easy', 'depth'), ('easy', 'recall'), ('easy', 'parity'), ('hard', 'depth'), ('hard', 'recall')):
        for size in ('small', 'large'):
            for seed in (0, 1, 2):
                suffix = f'{mode}-{size}-{task}-seed{seed}'
                cells[suffix] = {}
                for arm in ('softmax', *ARMS):
                    run = runs[f'{arm}-{suffix}']
                    cells[suffix][arm] = {
                        'pass_step': run['pass_step'], 'stop': run['stop'],
                        'best_sequence_accuracy': run['best_sequence_accuracy'],
                        'last_training_batch_loss': run['last_training_batch_loss'],
                        'final_sparsity': run['final_sparsity'],
                    }
    target = {}
    for seed in (0, 1, 2):
        suffix = f'hard-large-recall-seed{seed}'
        target[suffix] = {}
        for arm in ('softmax', 'qknorm-one', 'scaleddot', *ARMS):
            run = runs[f'{arm}-{suffix}']
            expected = copy.deepcopy(runs[f'softmax-{suffix}']['description'])
            for field in ('scores', 'weights'):
                expected['model']['block']['attention'][field] = run['description']['model']['block']['attention'][field]
            assert expected == run['description']
            assert run['trajectory'][0]['rows_sha256'] == runs[f'softmax-{suffix}']['trajectory'][0]['rows_sha256']
            target[suffix][arm] = {
                'pass_step': run['pass_step'], 'stop': run['stop'],
                'best_sequence_accuracy': run['best_sequence_accuracy'],
                'last_training_batch_loss': run['last_training_batch_loss'],
                'initial_query_statistics': run['trajectory'][0]['actual']['supervised_rows'],
                'final_query_statistics': run['trajectory'][-1]['actual']['supervised_rows'],
                'final_sparsity': run['final_sparsity'], 'final_head_scales': run['final_head_scales'],
            }
    program = Path(__file__).read_text()
    result = {
        'collected_utc': datetime.now(timezone.utc).isoformat(),
        'scope': 'Complete 60 new candidate runs, 30 contemporary softmax runs and six current target controls; other declared controls untrained',
        'training_code_commit': state['code_commit'], 'runtime_code_sha256': code_pin,
        'experiment_source_sha256': source_pin, 'completed_runs': len(runs),
        'raw_file_hashes_verified': raw_verified, 'comparisons': comparisons,
        'cells': cells, 'current_large_hard_recall_controls': target,
        'source_artifacts_sha256': {f'{size}_results.json': sha(EXPERIMENT / f'{size}_results.json') for size in parts},
        'small_control_repetition_sha256': sha(EXPERIMENT / 'small_control_repetition.json'),
        'preparation_sha256': sha(EXPERIMENT / 'preparation.json'),
        'program_source': program, 'program_sha256': hashlib.sha256(program.encode()).hexdigest(),
        'selection_limit': 'The old step-4 global QKNorm/ScaledDot counts come from separate trajectories. Current same-source comparisons with them cover only the three large hard-recall seeds.',
    }
    output = EXPERIMENT / 'results.json'
    output.write_text(json.dumps(result, indent=2) + '\n')
    print(json.dumps({'artifact': str(output), 'runs': len(runs), 'raw_hashes': raw_verified, 'comparisons': comparisons}))


if __name__ == '__main__':
    main()
